H=2*sum(heights)-2; W=2*11-2
out2=[[colors[0]]*W for _ in range(H)]
top=0
for c,h in zip(colors,heights):
    bottom=H-top; right=W-top
    for r in range(top,top+h):
        for col in range(top,right): out2[r][col]=c
    for r in range(bottom-h,bottom):
        for col in range(top,right): out2[r][col]=c
    for r in range(top,bottom):
        for col in range(top,top+h): out2[r][col]=c
        for col in range(right-h,right): out2[r][col]=c
    top+=h
print(H,W)
for row in out2: print(row)
